using OfficeIMO.Markdown;

namespace OfficeIMO.Notebook.Html;

/// <summary>Emits markup generated by the Notebook HTML adapter, outside the notebook's raw HTML path.</summary>
internal sealed class NotebookGeneratedHtmlBlock(string html) : IMarkdownBlock {
    public string RenderMarkdown() => string.Empty;
    public string RenderHtml() => html;
}
